head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Radio > P > renderType]<br/>컴포넌트가 렌더링 되는 방식을 설정합니다.",
    "validation" : [
        "미설정 시 table 태그를 갖는 div 태그로 렌더링됩니다.",
        "미설정 시 table 태그에 아이템이 정의되며, 아이템 항목은 두 개의 td 태그 하위에 각각 input, label 태그로 렌더링됩니다.",
        "table 설정 시 table 태그를 갖는 div 태그로 렌더링됩니다.",
        "table 설정 시 table 태그에 아이템이 정의되며, 아이템 항목은 두 개의 td 태그 하위에 각각 input, label 태그로 렌더링됩니다.",
        "native 설정 시 디자인 시 <xf:choice> 에 정의한 아이템은 무시되고, type='radio' 속성을 갖는 input 태그 하나로 렌더링됩니다.",
        "radiogroup 설정 시 tagname 과 itemTagname 속성값이 최상위 태그와 아이템 항목의 태그로 렌더링됩니다.",
        "radiogroup 설정 시 아이템 항목은 itemTagname 태그 하위에 input, label 태그로 렌더링됩니다.",
        "radiogroup 설정 시 아이템 항목은 itemTagname 태그 하위에 input, label 태그로 렌더링됩니다.",
        "radiogroup 설정 시 tagname, itemTagname 을 설정하지 않으면 div 태그가 적용됩니다.",
        "렌더링 되는 태그에 따라 'w2radio_main', 'w2radio_row', 'w2radio_td_input', 'w2radio_td_label', 'w2radio_item' 등의 클래스가 추가됩니다.",
        "아이템 항목에 해당하는 input, label 태그에는 각각 'w2radio_input', 'w2radio_label' 클래스가 추가됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        renderType : con_renderType.getText()
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출    
    $c.gcm.createBasicRadio(cList);    
}



scwin.btn_getRenderType_onclick = function (e) {
    let rtn = '';
    let renderType = con_renderType.getText();

    if (renderType == "native") {       
        rtn = target1.render.tagName;
        wf_body_bottom.getObj("scwin").setReturnValue("Main tagName : " + rtn);

        rtn = target1.render.className;
        wf_body_bottom.getObj("scwin").setReturnValue("Main className : " + rtn);

        rtn = target1.render.type;
        wf_body_bottom.getObj("scwin").setReturnValue("type : " + rtn);
    }

    else {
        rtn = target1.render.tagName;        
        wf_body_bottom.getObj("scwin").setReturnValue("Main tagName : " + rtn);

        rtn = target1.render.className;
        wf_body_bottom.getObj("scwin").setReturnValue("Main className : " + rtn);

        // id가 "target1"을 포함하는 모든 요소 찾기
        let matchingElements = document.querySelectorAll('[id*="target1"]');

        matchingElements.forEach(function(element) {
            let childElements = element.querySelectorAll("*"); // 모든 하위 요소 선택

            // 하위 요소들의 태그명 출력
            childElements.forEach(function(child) {
                rtn = child.tagName;
                wf_body_bottom.getObj("scwin").setReturnValue("Child tagName : " + rtn);

                rtn = child.className;
                wf_body_bottom.getObj("scwin").setReturnValue("Child className : " + rtn);

            });
        });
    }

};
